/* prog43_catalan – reproduced behaviour of the original binary
 *
 *   * prints "NO_INPUT"   when no argument is supplied
 *   * prints "BAD_INPUT"  when the argument is not a valid integer
 *   * prints "OUT_OF_RANGE" when the integer is larger than 30
 *   * otherwise prints the n‑th Catalan number (0‑based) and a newline
 *
 * The program matches the behaviour of the supplied binary for all
 * possible inputs.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char **argv)
{
    /* ----- no argument --------------------------------------------------- */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* ----- parse integer ------------------------------------------------- */
    char *endptr = NULL;
    errno = 0;
    long n = strtol(argv[1], &endptr, 10);

    /* conversion failed or extra characters after the number */
    if (endptr == argv[1] || *endptr != '\0' || errno != 0) {
        puts("BAD_INPUT");
        return 0;
    }

    /* ----- range checks -------------------------------------------------- */
    if (n < 0) {                     /* negative numbers are not accepted   */
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 30) {                    /* the DP table has only 31 entries    */
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ----- compute Catalan numbers -------------------------------------- */
    unsigned long long cat[31];
    cat[0] = 1ULL;                   /* C0 */

    for (int k = 1; k <= n; ++k) {
        unsigned long long sum = 0ULL;
        for (int i = 0; i < k; ++i) {
            sum += cat[i] * cat[k - 1 - i];
        }
        cat[k] = sum;
    }

    /* ----- output -------------------------------------------------------- */
    printf("%llu\n", cat[n]);
    return 0;
}
